    resign_confirm_dialog: "Arrendersi in questa partita?",
    new_game_confirm_dialog: "Iniziare una nuova partita? La partita attuale andrà persa, ma non verrà conteggiata come sconfitta nelle tue statistiche.",
    stats_empty: "Nessuna partita ancora giocata contro il computer.",
